import{_ as s,C as r,o,c as n,j as t,a as i,E as h,ak as d}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Scenario gaps & the Test Map","description":"The Test Map: one graph per project of what the application exposes and which tests reach it, and the scenario gaps it finds: routes, pages and controls no test reaches.","frontmatter":{"title":"Scenario gaps & the Test Map","description":"The Test Map: one graph per project of what the application exposes and which tests reach it, and the scenario gaps it finds: routes, pages and controls no test reaches.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/scenario-gaps.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/scenario-gaps.html"}],["meta",{"property":"og:title","content":"Scenario gaps & the Test Map | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The Test Map: one graph per project of what the application exposes and which tests reach it, and the scenario gaps it finds: routes, pages and controls no test reaches."}]]},"headers":[],"relativePath":"features/scenario-gaps.md","filePath":"features/scenario-gaps.md","lastUpdated":1790798161000}'),c={name:"features/scenario-gaps.md"};function p(l,e,g,u,f,m){const a=r("Needs");return o(),n("div",null,[e[0]||(e[0]=t("h1",{id:"scenario-gaps-the-test-map",tabindex:"-1"},[i("Scenario gaps & the Test Map "),t("a",{class:"header-anchor",href:"#scenario-gaps-the-test-map","aria-label":'Permalink to "Scenario gaps & the Test Map"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p>The test catalog lists the tests you have. <strong>Scenario gaps</strong> describe the ones you don&#39;t: the route no test requests, the page nothing visits, the test that is the only thing standing between a page and no test at all. Each gap is a suggestion with its evidence and a next step, never a verdict.</p><p>Gaps come from the <strong><a href="/guide/concepts.html#test-map">Test Map</a></strong>: one graph per project of what the application exposes (routes, pages, controls, links, and the handlers and dependencies behind them) and which tests <a href="/guide/concepts.html#reach">reach</a> each of them. It is built from what the reporter and the <a href="/guide/capture-fixtures.html">capture fixtures</a> already record: the requests and page visits of every run.</p><blockquote><p><strong>Observed reach, not coverage.</strong> A gap says a test <em>observably reached</em> something, or that nothing did, measured from real runs, never from instrumented code coverage. &quot;No edge&quot; means &quot;no evidence&quot;, not &quot;proof of absence&quot;.</p></blockquote><h2 id="what-a-gap-is" tabindex="-1">What a gap is <a class="header-anchor" href="#what-a-gap-is" aria-label="Permalink to &quot;What a gap is&quot;">​</a></h2><p>A <strong><a href="/guide/concepts.html#detector">detector</a></strong> reads the Test Map and the last 30 runs and reports one kind of gap: a route observed only with success statuses, a node exactly one test reaches, a page that appeared in the latest run, a declared route nothing requests. <a href="/reference/gap-detectors.html">Gap detectors &amp; exposure</a> lists every detector with its evidence. Each gap names its detector and its <strong><a href="/guide/concepts.html#gap-class">class</a></strong>:</p><table tabindex="0"><thead><tr><th>Class</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><strong>blind-spot</strong></td><td>nothing reaches it</td><td><code>Observed 412 times over the last 30 runs, always 200</code></td></tr><tr><td><strong>false-comfort</strong></td><td>a <a href="/features/probes.html">probe</a> broke it and every test still passed</td><td><code>Tests pass when POST /api/orders breaks</code></td></tr><tr><td><strong>fragile</strong></td><td>what reaches it could stop at any time</td><td><code>Only checkout › coupon reaches this</code></td></tr></tbody></table><p><a href="/features/probes.html#server-probes">Server probes</a> add <strong>findings</strong> in two more classes, <strong>unhandled</strong> and <strong>degraded</strong>: the application itself did not cope with the fault, whatever the tests saw.</p><p>Gaps are ranked by <strong><a href="/guide/concepts.html#exposure">exposure</a></strong>, a score from how often the code around a node changes, how old it is, whether it was part of an earlier escaped failure, and the priority of the tests near it. The score and its factors show on every gap. Counts are per class, never a coverage percentage: a percentage over an observed surface looks complete exactly when that surface is sparse.</p><p>A changed file no test reaches is a gap too, raised at pull-request time: see <a href="/features/uncovered-changes.html">Uncovered changes in pull requests</a>. So is a page with open <a href="/features/bug-reports.html">bug reports</a>: a defect that escaped the suite there.</p><h2 id="the-gaps-tab" tabindex="-1">The Gaps tab <a class="header-anchor" href="#the-gaps-tab" aria-label="Permalink to &quot;The Gaps tab&quot;">​</a></h2><p>The project page has a <strong>Gaps</strong> tab: gaps and findings grouped by feature and ranked, each with its class, its score factors and its evidence lines.</p><p>The tab opens on the <strong>feature map</strong>: one circle per feature (from the <a href="/reference/test-metadata.html"><code>piwi:feature</code> tag</a>), sized by the routes, pages and controls it groups, colored by its worst open gap, and linked to the features it shares nodes with. The ranked list beside it carries every feature, however many.</p><p>A feature, or a gap&#39;s node, opens in the <strong>feature graph</strong>: the node in the middle, what leads into it on the left, what it leads to on the right, nodes colored by class and edges by kind. The picture shows the most severe few of each kind; the <strong>neighbors</strong> list under it has every neighbor, with its relation, worst gap and reaching tests. Click a node to recenter on it. Agents walk the same graph with the <a href="/reference/mcp-tools.html#get_feature_graph"><code>get_feature_graph</code></a> MCP tool.</p><h2 id="triage" tabindex="-1">Triage <a class="header-anchor" href="#triage" aria-label="Permalink to &quot;Triage&quot;">​</a></h2><p>Every gap takes the same four verbs as an inbox item:</p><ul><li><strong>Accept</strong> copies a draft test skeleton to your clipboard: a title from the gap, the <code>piwi:</code> annotations of the nearest test, the path from a reached page to the gap as steps, and a TODO where the assertion goes.</li><li><strong>Snooze</strong> for a day, a week, or until the node changes.</li><li><strong>Dismiss</strong> with a reason: <em>not worth testing</em>, <em>covered elsewhere</em> (which records the covering test as reaching the node), or <em>wrong</em>.</li><li><strong>Covered by</strong> records a covering test without dismissing the gap.</li></ul><p>Gaps persist, so triage survives recomputation: a dismissed gap keeps its verdict, and a gap <strong>closes itself</strong> when the detector no longer finds it, for example once its node gains a trusted test, so &quot;closed this month&quot; is real. A closed gap that comes back reopens. Home lists the gaps accepted more than a week ago whose test was never written. The map is recomputed after every run and nightly.</p><p>Every verdict is also a labeled example: accepted and covered-by count <em>for</em> a detector, dismissed as <em>wrong</em> counts <em>against</em> it. A detector below 60% precision on a project with twenty or more verdicts <strong>mutes itself</strong> there: its rows leave the pull-request comment, and the Gaps tab and <strong>Settings → About</strong> say so.</p><p>The top new gaps of each project are the <strong>Gaps digest</strong><a href="/features/quality-reports.html#what-a-report-contains">quality report</a>; <a href="/features/quality-reports.html#report-schedules">schedule it</a> to your channels. Agents list and draft gaps with <a href="/reference/mcp-tools.html#list_scenario_gaps"><code>list_scenario_gaps</code></a> and <a href="/reference/mcp-tools.html#draft_scenario"><code>draft_scenario</code></a>, and the <a href="/features/agent-skills.html">write-the-missing-test</a> skill drives the loop.</p><h2 id="what-feeds-the-map" tabindex="-1">What feeds the map <a class="header-anchor" href="#what-feeds-the-map" aria-label="Permalink to &quot;What feeds the map&quot;">​</a></h2><p>Every run adds the routes its tests requested on the application&#39;s own origin and the pages they navigated to. Three optional sources add the rest:</p><ul><li><strong>The page inventory.</strong> With <code>capturePageInventory</code> on (off by default), the reporter records the controls (role and accessible name) and links of each page a passing run visits, at most 200 of each per page, never a field value. Control and link nodes, and the detectors that read them, appear only then. See <a href="/guide/concepts.html#page-inventory">Page inventory</a>.</li><li><strong>Server spans.</strong> With the <a href="/guide/backend-logs.html#server-spans">backend instrumentation</a> for Nitro, each route gains the handler that served it and the dependencies that handler called.</li><li><strong>The declared surface</strong>, below.</li></ul><h3 id="declared-surface" tabindex="-1">Declared surface <a class="header-anchor" href="#declared-surface" aria-label="Permalink to &quot;Declared surface&quot;">​</a></h3><p>Beyond what tests observe, the map can hold what the application <em>declares</em> it exposes, so a route or page nothing reaches is named a <strong>declared, never hit</strong> blind spot instead of staying invisible. Three sources feed it:</p><ul><li><strong>The instrumentation&#39;s route manifest.</strong> The <a href="/guide/backend-logs.html#route-manifest">Nitro plugin</a> serves the routes it has matched at <code>/__piwi/manifest</code> outside production, and the reporter uploads it with the run. The ASP.NET Core package serves no manifest.</li><li><strong>A committed manifest.</strong> A <code>piwi.manifest.json</code> next to your Playwright config (<code>{ &quot;routes&quot;: [...], &quot;pages&quot;: [...] }</code>) is uploaded whenever present, whatever the backend.</li><li><strong>An OpenAPI URL</strong>, set per project. Piwi fetches the document on a recompute and records each route&#39;s documented response codes, so a <em>success only</em> gap can name the error codes a route documents but never returned under test.</li></ul><h2 id="what-this-is-not" tabindex="-1">What this is not <a class="header-anchor" href="#what-this-is-not" aria-label="Permalink to &quot;What this is not&quot;">​</a></h2><ul><li><strong>Not coverage.</strong> Every surface says <em>observed reach</em>.</li><li><strong>Not a test generator.</strong> A gap proposes a scenario; the assertion is yours.</li><li><strong>Not a gate.</strong> Uncovered changes can only warn; see <a href="/features/uncovered-changes.html#the-gate-flag">the gate flag</a>.</li><li><strong>Not a percentage.</strong> Counts per class, ranked by exposure.</li></ul><p>The Test Map and its server probes are optional: <a href="/operate/capabilities.html#declining-a-capability">decline</a> either per project or for the instance, and these surfaces disappear.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/features/uncovered-changes.html">Uncovered changes in pull requests</a>: the changed files no test reaches</li><li><a href="/features/probes.html">Probes</a>: whether a test that reaches a route would notice it breaking</li><li><a href="/reference/gap-detectors.html">Gap detectors &amp; exposure</a>: every detector, the exposure factors, what the graph includes</li><li><a href="/guide/concepts.html#test-map">Core concepts</a>: the Test Map vocabulary</li><li><a href="/features/agent-skills.html">Agent skills</a>: write-the-missing-test</li></ul>',30))])}const v=s(c,[["render",p]]);export{w as __pageData,v as default};
